function solve(edges) {
  const e = Math.floor(edges.length / 2);
  if (e === 0) return [0];
  const order = [];
  for (let i = 0; i < e; i++) order.push(i);
  order.sort((a, b) => {
    if (edges[2 * a] !== edges[2 * b]) return edges[2 * a] - edges[2 * b];
    if (edges[2 * a + 1] !== edges[2 * b + 1]) return edges[2 * a + 1] - edges[2 * b + 1];
    return a - b;
  });
  const used = new Array(e).fill(false);
  const path = [0];
  function search(node, count) {
    if (count === e) return true;
    for (let t = 0; t < e; t++) {
      const t2 = order[t];
      if (used[t2]) continue;
      if (edges[2 * t2] !== node) continue;
      used[t2] = true;
      path.push(edges[2 * t2 + 1]);
      if (search(edges[2 * t2 + 1], count + 1)) return true;
      path.pop();
      used[t2] = false;
    }
    return false;
  }
  if (search(0, 0)) return path;
  return [];
}

function solve(edges) {
  const e = Math.floor(edges.length / 2);
  if (e === 0) return [0];
  const adj = new Map();
  for (let t = 0; t < e; t++) {
    const u = edges[2 * t];
    if (!adj.has(u)) adj.set(u, []);
    adj.get(u).push(edges[2 * t + 1]);
  }
  adj.forEach((list) => list.sort((a, b) => a - b));
  const stack = [0];
  const out = [];
  while (stack.length > 0) {
    const u = stack[stack.length - 1];
    const list = adj.get(u);
    if (list !== undefined && list.length > 0) {
      stack.push(list.shift());
    } else {
      out.push(stack.pop());
    }
  }
  if (out.length !== e + 1) return [];
  out.reverse();
  const need = new Map();
  for (let t = 0; t < e; t++) {
    const key = edges[2 * t] + "," + edges[2 * t + 1];
    need.set(key, (need.get(key) || 0) + 1);
  }
  for (let i = 0; i + 1 < out.length; i++) {
    const key = out[i] + "," + out[i + 1];
    const left = need.get(key);
    if (left === undefined || left === 0) return [];
    need.set(key, left - 1);
  }
  return out;
}
